insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  9,
  $wyb$A Flask webhook that receives real Typeform form submissions, asks an AI model to score each lead 1-10 against your Ideal Customer Profile and explain why in one sentence, then creates a HubSpot contact carrying that score and a follow-up task due sooner for hotter leads. A rule-based shortcut skips the AI call entirely for leads that are obviously a bad fit, saving credits and avoiding an unpredictable AI judgment where a simple rule is more reliable.$wyb$,
  $wyl$["Parse Typeform's real webhook payload, including its per-question-type answer shapes", "Write a lead-scoring prompt grounded in an explicit Ideal Customer Profile", "Parse a bracket-marker AI reply defensively, including a malformed one", "Decide which decisions belong to the AI and which belong to plain Python", "Build real HubSpot Contacts and Tasks API request payloads as pure, testable functions", "Test a Flask webhook end-to-end with fake network responses, without live credentials", "Turn a raw score into a follow-up SLA where hotter leads get followed up sooner"]$wyl$::jsonb,
  $sess${"model": "Claude Haiku 4.5 (via your AI Builder credits)", "totalTime": "110 min", "buildCount": 5, "whatYouNeed": ["Your AI Builder key (Credits page on your dashboard)", "Python 3.10+ installed", "A free Typeform account", "A HubSpot account (the free CRM tier works)"], "outcomes": ["Parse Typeform's real webhook payload into a simple lead dict", "Have the AI score each lead against your Ideal Customer Profile and explain why", "Turn a score into a hot/warm/cold tier without spending an extra AI call", "Build the exact HubSpot contact and follow-up task payloads the Contacts and Tasks APIs expect", "Test the entire pipeline end-to-end without a live Typeform form or a HubSpot account"], "builds": [{"number": 1, "title": "Parse a real Typeform webhook payload", "time": "20 min", "description": "Typeform's webhook payload is deeply nested and shaped differently for every question type. Get the parsing right first, in isolation, before any AI or HubSpot code depends on it.", "steps": [{"instruction": "Create `webhook.py` with this code:", "prompt": "\"\"\"\nStep 1 of the Lead Capture & Qualifier Bot.\n\nThis file has one job: take the raw JSON Typeform sends to your webhook\nand turn it into a plain Python dict with the answers you actually care\nabout. Typeform's real payload is deeply nested (a form definition, an\nanswers list, a different shape per question type) - this hides all of\nthat so the rest of the project can just do lead[\"email\"], lead[\"company\"],\nand so on.\n\"\"\"\n\n# The six questions this project's Typeform form is expected to have,\n# and the exact title text used for each. Typeform gives every field a\n# random ID that's different on every form, so title text - not ID - is\n# what we use to line an answer up with a field. If you rename a\n# question in Typeform, update the matching value here too.\nFIELD_TITLES = {\n    \"full_name\": \"Full name\",\n    \"email\": \"Work email\",\n    \"company\": \"Company name\",\n    \"company_size\": \"Company size\",\n    \"budget\": \"Budget range\",\n    \"challenge\": \"What's your biggest challenge right now?\",\n}\n\n\ndef _value_from_answer(answer):\n    \"\"\"\n    Typeform sends a different JSON shape per question type - a short\n    text answer looks nothing like a multiple-choice answer. This is\n    the full list of shapes this form's six questions can use; see the\n    Typeform webhook docs linked in this course's Resources for the\n    handful of other types (files, dates, ratings) this form doesn't.\n    \"\"\"\n    answer_type = answer.get(\"type\")\n    if answer_type == \"text\":\n        return answer.get(\"text\", \"\")\n    if answer_type == \"email\":\n        return answer.get(\"email\", \"\")\n    if answer_type == \"number\":\n        return answer.get(\"number\")\n    if answer_type == \"choice\":\n        # Single-select multiple choice: {\"choice\": {\"label\": \"...\"}}\n        return answer.get(\"choice\", {}).get(\"label\", \"\")\n    if answer_type == \"choices\":\n        # Multi-select: {\"choices\": {\"labels\": [\"...\", \"...\"]}}\n        return \", \".join(answer.get(\"choices\", {}).get(\"labels\", []))\n    if answer_type == \"boolean\":\n        return answer.get(\"boolean\")\n    # A field type this project doesn't use (e.g. a file upload). Returning\n    # None instead of raising means one unexpected question type can't take\n    # down the whole webhook - see this course's Troubleshooting section.\n    return None\n\n\ndef parse_typeform_payload(payload):\n    \"\"\"\n    Turns a raw Typeform webhook body into a simple lead dict.\n\n        lead = parse_typeform_payload(request.get_json())\n        lead[\"email\"]    # \"jane@acme.com\"\n        lead[\"company\"]  # \"Acme Inc\"\n\n    A question Typeform doesn't return an answer for (skipped because it\n    wasn't required, or bypassed by Logic Jump) comes back as \"\" here\n    rather than raising - Typeform only includes answered questions in\n    the payload, so a missing one is normal, not an error.\n    \"\"\"\n    form_response = payload.get(\"form_response\", {})\n\n    # Every webhook delivery includes the form's own field definitions,\n    # not just the answers - which is what lets us build a\n    # {field_id: title} lookup here instead of hardcoding your form's\n    # (randomly generated, different-per-form) field IDs anywhere.\n    fields = form_response.get(\"definition\", {}).get(\"fields\", [])\n    title_by_id = {field[\"id\"]: field[\"title\"] for field in fields}\n\n    answers_by_title = {}\n    for answer in form_response.get(\"answers\", []):\n        field_id = answer.get(\"field\", {}).get(\"id\")\n        title = title_by_id.get(field_id)\n        if title is None:\n            continue\n        answers_by_title[title] = _value_from_answer(answer)\n\n    return {\n        key: answers_by_title.get(title, \"\")\n        for key, title in FIELD_TITLES.items()\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works: python webhook.py\n    #\n    # This is a trimmed but structurally real Typeform webhook payload -\n    # the same shape Typeform actually sends, just missing extra fields\n    # (like \"hidden\" or \"landed_at\") this project doesn't read.\n    # parse_typeform_payload() ignores anything it doesn't recognise, so\n    # trimming those out here doesn't change what's being tested.\n    FAKE_PAYLOAD = {\n        \"event_id\": \"LtWXD3crgy\",\n        \"event_type\": \"form_response\",\n        \"form_response\": {\n            \"form_id\": \"abc123\",\n            \"token\": \"a3a12ec67\",\n            \"submitted_at\": \"2026-08-20T10:15:00Z\",\n            \"definition\": {\n                \"id\": \"abc123\",\n                \"title\": \"Book a demo\",\n                \"fields\": [\n                    {\"id\": \"f_name\", \"title\": \"Full name\", \"type\": \"short_text\"},\n                    {\"id\": \"f_email\", \"title\": \"Work email\", \"type\": \"email\"},\n                    {\"id\": \"f_company\", \"title\": \"Company name\", \"type\": \"short_text\"},\n                    {\"id\": \"f_size\", \"title\": \"Company size\", \"type\": \"multiple_choice\"},\n                    {\"id\": \"f_budget\", \"title\": \"Budget range\", \"type\": \"multiple_choice\"},\n                    {\"id\": \"f_challenge\", \"title\": \"What's your biggest challenge right now?\", \"type\": \"long_text\"},\n                ],\n            },\n            \"answers\": [\n                {\"type\": \"text\", \"text\": \"Jane Okafor\", \"field\": {\"id\": \"f_name\", \"type\": \"short_text\"}},\n                {\"type\": \"email\", \"email\": \"jane@acme.com\", \"field\": {\"id\": \"f_email\", \"type\": \"email\"}},\n                {\"type\": \"text\", \"text\": \"Acme Inc\", \"field\": {\"id\": \"f_company\", \"type\": \"short_text\"}},\n                {\"type\": \"choice\", \"choice\": {\"label\": \"51-200\"}, \"field\": {\"id\": \"f_size\", \"type\": \"multiple_choice\"}},\n                {\"type\": \"choice\", \"choice\": {\"label\": \"$5k-$10k/month\"}, \"field\": {\"id\": \"f_budget\", \"type\": \"multiple_choice\"}},\n                {\"type\": \"text\", \"text\": \"Our reporting is all manual spreadsheets.\", \"field\": {\"id\": \"f_challenge\", \"type\": \"long_text\"}},\n            ],\n        },\n    }\n\n    lead = parse_typeform_payload(FAKE_PAYLOAD)\n    print(\"Parsed lead:\", lead)\n\n    assert lead[\"email\"] == \"jane@acme.com\"\n    assert lead[\"company\"] == \"Acme Inc\"\n    assert lead[\"company_size\"] == \"51-200\"\n    assert lead[\"challenge\"] == \"Our reporting is all manual spreadsheets.\"\n    print(\"\\nParsing works.\")\n", "verify": "Run `python webhook.py` \u2014 you should see `Parsed lead: {...}` with all six fields filled in, followed by `Parsing works.`"}], "goFurther": "Typeform payloads also include a `hidden` object for tracking parameters (like a UTM source) passed in the form's URL. Add a `source` key to the lead dict that reads `form_response.get(\"hidden\", {}).get(\"utm_source\", \"unknown\")`."}, {"number": 2, "title": "Score leads with AI", "time": "25 min", "description": "This is the one AI call in the whole project \u2014 everything before it prepares the input, everything after it (the HubSpot payloads) just uses the output. Get this one right and the rest is plumbing.", "steps": [{"instruction": "Create `scorer.py` with this code:", "prompt": "\"\"\"\nStep 2 of the Lead Capture & Qualifier Bot.\n\nThis file has one job: given a lead dict, ask the AI how good a fit it\nis and get back a score and a one-line reason. Everything about WHO\ncounts as a good lead - your Ideal Customer Profile (ICP) - lives here,\nin one prompt. Change the ICP text below and every future lead is\nscored against your new criteria - no other file needs to change.\n\"\"\"\n\nimport re\n\nfrom sdt_ai import ask_ai, AIError\n\n# Your Ideal Customer Profile. This is deliberately just English, not\n# code - tune it the way you'd brief a new sales rep. The default below\n# matches a common B2B SaaS ICP; replace it with your own before this\n# goes live for a real business.\nICP = \"\"\"\nIdeal customer profile:\n- Company size: 51-200 employees is the sweet spot. Under 10 is usually\n  too small to have budget authority; over 200 usually means a longer,\n  committee-based sales cycle.\n- Budget: $5,000/month or more is a strong signal of real intent.\n- Pain points we solve well: manual reporting, slow customer onboarding,\n  and disconnected tools that don't talk to each other.\n\"\"\".strip()\n\n\ndef build_prompt(lead):\n    \"\"\"\n    Writes the instructions we send to the AI. Kept in its own function\n    so you can print it and read exactly what the AI sees - the fastest\n    way to fix a score that doesn't match your own judgment.\n    \"\"\"\n    return f\"\"\"Score this sales lead against the Ideal Customer Profile below.\n\n{ICP}\n\nLEAD:\nCompany: {lead.get('company', 'unknown')}\nCompany size: {lead.get('company_size', 'unknown')}\nBudget: {lead.get('budget', 'unknown')}\nStated challenge: {lead.get('challenge', 'unknown')}\n\nGive a score from 1 to 10, where 10 is a perfect fit for the ICP above\nand 1 is a very poor fit. Then give ONE sentence explaining the score.\n\nFormat your answer EXACTLY like this:\n\n[SCORE]\na single number from 1 to 10, nothing else on that line\n[REASON]\none sentence explaining the score\n[END]\n\nDo not add any explanation, introduction or closing remark outside\nthose markers.\"\"\"\n\n\ndef parse_score_reply(reply):\n    \"\"\"\n    Pulls the score and reason out of the AI's [SCORE]/[REASON]/[END]\n    reply.\n\n    We use bracket markers instead of asking for JSON for the same\n    reason the Social Post Generator does: JSON breaks the moment the\n    AI adds a stray comma or wraps the answer in ``` fences, and that\n    is a miserable first bug to debug when you're starting out. Markers\n    degrade more gracefully - anything we don't recognise is ignored\n    rather than crashing the parse.\n\n    Raises ValueError with a specific, readable message if the [SCORE]\n    section is missing or contains no number at all - see the\n    self-test below for exactly which malformed replies this catches.\n    \"\"\"\n    sections = {}\n    current = None\n    lines = []\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker in (\"SCORE\", \"REASON\"):\n            if current:\n                sections[current] = \"\\n\".join(lines).strip()\n            current = marker\n            lines = []\n        elif current:\n            lines.append(line)\n\n    if current:\n        sections[current] = \"\\n\".join(lines).strip()\n\n    score_text = sections.get(\"SCORE\", \"\")\n\n    # The AI was told to reply with \"a single number\" but models don't\n    # always follow formatting instructions to the letter - a common\n    # drift is writing \"8/10\" or \"Score: 8\" instead of a bare \"8\".\n    # Searching for the FIRST run of digits copes with both of those\n    # with no extra prompting, while still failing loudly (rather than\n    # silently defaulting to some made-up number) if there is genuinely\n    # no digit anywhere in the reply.\n    match = re.search(r\"\\d+\", score_text)\n    if not match:\n        raise ValueError(\n            \"Could not find a numeric score in the AI's reply.\\n\"\n            f\"The [SCORE] section contained: {score_text!r}\\n\"\n            \"Run `python scorer.py` to see the exact parsing rules against \"\n            \"known-good and known-bad replies, or print(reply) inside \"\n            \"score_lead() to see the raw AI output that caused this.\"\n        )\n\n    score = int(match.group())\n    # Clamp rather than reject: a 1-10 prompt occasionally gets an 11 or\n    # a 0 back. Clamping keeps the pipeline running with a sane value\n    # instead of failing a whole webhook delivery over one stray point.\n    score = max(1, min(10, score))\n\n    reason = sections.get(\"REASON\", \"\").strip() or \"No reason given.\"\n\n    return {\"score\": score, \"reason\": reason}\n\n\ndef score_to_tier(score):\n    \"\"\"\n    1-10 -> hot/warm/cold. A plain if/else, not a second AI call - the\n    AI's job here is judgment (how good a fit is this lead), not\n    arithmetic (which bucket does this number fall into). Doing the\n    bucketing in Python makes it 100% consistent between leads and\n    costs zero extra credits.\n    \"\"\"\n    if score >= 8:\n        return \"hot\"\n    if score >= 5:\n        return \"warm\"\n    return \"cold\"\n\n\ndef score_lead(lead):\n    \"\"\"\n    The main function. Give it a lead dict, get back its score, tier\n    and reason.\n\n        result = score_lead(lead)\n        result[\"score\"]   # 8\n        result[\"tier\"]    # \"hot\"\n        result[\"reason\"]  # \"Mid-size company matching two of three ICP signals.\"\n    \"\"\"\n    prompt = build_prompt(lead)\n\n    # The whole reply is a number and one sentence, so max_tokens=150 is\n    # generous, not tight - this is the cheapest AI call in the course.\n    # Compare to the Social Post Generator's max_tokens=1200 for five\n    # full posts: shorter expected output should always mean a lower cap.\n    reply = ask_ai(prompt, max_tokens=150, project=\"lead-capture-qualifier-bot\")\n\n    result = parse_score_reply(reply)\n    result[\"tier\"] = score_to_tier(result[\"score\"])\n    return result\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parser: python scorer.py\n    #\n    # This does NOT call the AI - it feeds parse_score_reply() fake\n    # replies, including a malformed one, so you can check the parsing\n    # logic for free before ever spending a credit.\n\n    good_reply = \"[SCORE]\\n8\\n[REASON]\\nMid-size company with clear budget and a matching pain point.\\n[END]\"\n    result = parse_score_reply(good_reply)\n    print(\"Well-formatted reply ->\", result)\n    assert result[\"score\"] == 8\n    assert \"budget\" in result[\"reason\"]\n\n    # A common way real models drift from instructions: writing \"8/10\"\n    # instead of a bare \"8\". The regex search for the first run of\n    # digits copes with this without any special-casing.\n    messy_reply = \"[SCORE]\\n8/10\\n[REASON]\\nGood fit overall.\\n[END]\"\n    result = parse_score_reply(messy_reply)\n    print(\"Messy '8/10' reply ->\", result)\n    assert result[\"score\"] == 8\n\n    # A reply with no digit anywhere should fail loudly, not silently\n    # return some made-up default.\n    try:\n        parse_score_reply(\"[SCORE]\\nfairly good\\n[REASON]\\nSeems fine.\\n[END]\")\n        raise AssertionError(\"Expected a ValueError for a non-numeric score\")\n    except ValueError as problem:\n        print(\"\\nCorrectly rejected a non-numeric score:\")\n        print(problem)\n\n    print(\"\\nAll parser checks passed.\")\n", "verify": "Run `python scorer.py` \u2014 you should see the well-formatted reply scored correctly, the messy `8/10` reply ALSO scored correctly, then a message confirming a non-numeric reply is correctly rejected. This test does not call the AI, so it costs no credits."}], "goFurther": "Break it on purpose: call `score_lead()` with a lead where `company_size`, `budget` and `challenge` are all empty strings. This DOES spend a small number of real credits (it's a real AI call), so only do it once. What score comes back? The ICP prompt never tells the AI what to do with missing information, so nothing here stops it from guessing a confident-sounding number for a lead you know nothing about \u2014 the parser only checks that the reply LOOKS like a valid score (a number 1-10), not that the score is trustworthy. Real protection would have to live in the prompt (tell the AI explicitly how to handle blank fields) or in Python (refuse to score a lead that's missing required fields at all) \u2014 not in the parser."}, {"number": 3, "title": "Push scored leads into HubSpot", "time": "25 min", "description": "Set up the HubSpot side by hand first \u2014 the Private App token and the custom properties \u2014 then build (and test) the exact request payloads Python needs to send.", "steps": [{"instruction": "In HubSpot, go to Settings \u2192 Integrations \u2192 Private Apps, create an app with the scopes `crm.objects.contacts.read`, `crm.objects.contacts.write` and `crm.objects.tasks.write`, then copy its access token.", "verify": "You should see a token starting with `pat-` \u2014 HubSpot only shows it once, so paste it into your `.env` as `HUBSPOT_API_KEY` right away."}, {"instruction": "In HubSpot, go to Settings \u2192 Properties \u2192 Contact properties, and create three custom properties: `lead_score` (Number), `lead_tier` (Single-line text) and `ai_notes` (Multi-line text).", "verify": "All three should now appear in the Contact properties list."}, {"instruction": "Create `hubspot_client.py` with this code:", "prompt": "\"\"\"\nStep 3 of the Lead Capture & Qualifier Bot.\n\nThis file builds the HubSpot API requests that create a contact and a\nfollow-up task. Building the request (a plain Python dict) is kept\ncompletely separate from sending it (one requests.post call) - that\nsplit is what lets you test and trust the payload shape without ever\nneeding a real HubSpot account, and it is why send_to_hubspot() is the\none function you swap out in tests (see main.py's self-test).\n\"\"\"\n\nimport os\n\nfrom datetime import datetime, timedelta, timezone\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Loaded again here (sdt_ai.py also loads it) so this file's own\n# self-test and any standalone use of it works no matter which file\n# happens to be imported first - load_dotenv() is safe to call more\n# than once.\nload_dotenv()\n\nHUBSPOT_BASE = \"https://api.hubapi.com\"\n\n# Hot leads get a follow-up task due in 2 hours; everything else gets\n# 24. This mirrors a real sales team's SLA: a lead that looks like a\n# strong fit goes cold fast if nobody calls back the same day.\nFOLLOW_UP_HOURS = {\"hot\": 2, \"warm\": 24, \"cold\": 24}\n\n\ndef build_contact_payload(lead, score_result):\n    \"\"\"\n    Builds the request body for POST /crm/v3/objects/contacts.\n\n    This is a pure function - no network call, nothing to configure -\n    so you can test it with any lead dict and check the exact shape of\n    what would be sent, without a HubSpot account or API key at all.\n\n    Assumes three custom contact properties already exist in your\n    HubSpot account: lead_score (Number), lead_tier (Single-line text)\n    and ai_notes (Multi-line text). Create them under Settings >\n    Properties before your first real submission (see Build 3).\n    \"\"\"\n    full_name = lead.get(\"full_name\", \"\").strip()\n    first_name, _, last_name = full_name.partition(\" \")\n\n    return {\n        \"properties\": {\n            \"email\": lead.get(\"email\", \"\"),\n            \"firstname\": first_name,\n            \"lastname\": last_name,\n            \"company\": lead.get(\"company\", \"\"),\n            \"lead_score\": str(score_result[\"score\"]),\n            \"lead_tier\": score_result[\"tier\"],\n            \"ai_notes\": score_result[\"reason\"],\n        }\n    }\n\n\ndef build_task_payload(contact_id, lead, score_result):\n    \"\"\"\n    Builds the request body for POST /crm/v3/objects/tasks, with the\n    association to the contact included in the same request - HubSpot\n    lets you create and associate a task in one call instead of two.\n\n    associationTypeId 204 is HubSpot's built-in \"task to contact\" link\n    type - a fixed number HubSpot itself defines, not something you\n    choose, so it's hardcoded here rather than made configurable.\n    \"\"\"\n    tier = score_result[\"tier\"]\n    due_at = datetime.now(timezone.utc) + timedelta(hours=FOLLOW_UP_HOURS[tier])\n\n    return {\n        \"properties\": {\n            \"hs_task_subject\": (\n                f\"Follow up: {lead.get('company', 'unknown company')} \"\n                f\"({tier.upper()} - {score_result['score']}/10)\"\n            ),\n            \"hs_task_body\": score_result[\"reason\"],\n            # HubSpot expects an ISO 8601 timestamp with millisecond\n            # precision, e.g. \"2026-08-20T12:30:00.000Z\".\n            \"hs_timestamp\": due_at.strftime(\"%Y-%m-%dT%H:%M:%S.%f\")[:-3] + \"Z\",\n            \"hs_task_status\": \"NOT_STARTED\",\n            \"hs_task_priority\": \"HIGH\" if tier == \"hot\" else \"MEDIUM\",\n        },\n        \"associations\": [\n            {\n                \"to\": {\"id\": contact_id},\n                \"types\": [\n                    {\"associationCategory\": \"HUBSPOT_DEFINED\", \"associationTypeId\": 204}\n                ],\n            }\n        ],\n    }\n\n\ndef send_to_hubspot(endpoint, payload, api_key):\n    \"\"\"\n    The one function that actually talks to HubSpot. Every other\n    function in this file is pure (just builds a dict) precisely so\n    this is the only thing that needs replacing with a stub in tests -\n    see main.py's self-test, which swaps this out for a fake that\n    returns a made-up ID instead of making a real request.\n    \"\"\"\n    response = requests.post(\n        f\"{HUBSPOT_BASE}{endpoint}\",\n        headers={\n            \"Authorization\": f\"Bearer {api_key}\",\n            \"Content-Type\": \"application/json\",\n        },\n        json=payload,\n        timeout=15,\n    )\n    response.raise_for_status()\n    return response.json()\n\n\ndef create_contact(lead, score_result):\n    \"\"\"Creates the HubSpot contact and returns its new contact ID.\"\"\"\n    api_key = os.environ.get(\"HUBSPOT_API_KEY\")\n    payload = build_contact_payload(lead, score_result)\n    result = send_to_hubspot(\"/crm/v3/objects/contacts\", payload, api_key)\n    return result[\"id\"]\n\n\ndef create_followup_task(contact_id, lead, score_result):\n    \"\"\"Creates the follow-up task, already associated with the contact.\"\"\"\n    api_key = os.environ.get(\"HUBSPOT_API_KEY\")\n    payload = build_task_payload(contact_id, lead, score_result)\n    return send_to_hubspot(\"/crm/v3/objects/tasks\", payload, api_key)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the payloads: python hubspot_client.py\n    #\n    # This never calls send_to_hubspot() or touches the network - it only\n    # checks that build_contact_payload() and build_task_payload() produce\n    # the shape HubSpot's Contacts and Tasks APIs actually expect, which\n    # you can verify against the docs linked in this course's Resources\n    # without needing a HubSpot account yet.\n    fake_lead = {\n        \"full_name\": \"Jane Okafor\",\n        \"email\": \"jane@acme.com\",\n        \"company\": \"Acme Inc\",\n        \"company_size\": \"51-200\",\n        \"budget\": \"$5k-$10k/month\",\n        \"challenge\": \"Our reporting is all manual spreadsheets.\",\n    }\n    fake_score = {\"score\": 9, \"tier\": \"hot\", \"reason\": \"Strong fit on size and budget.\"}\n\n    contact_payload = build_contact_payload(fake_lead, fake_score)\n    print(\"Contact payload:\", contact_payload)\n    assert contact_payload[\"properties\"][\"email\"] == \"jane@acme.com\"\n    assert contact_payload[\"properties\"][\"firstname\"] == \"Jane\"\n    assert contact_payload[\"properties\"][\"lastname\"] == \"Okafor\"\n    assert contact_payload[\"properties\"][\"lead_score\"] == \"9\"\n\n    task_payload = build_task_payload(\"12345\", fake_lead, fake_score)\n    print(\"\\nTask payload:\", task_payload)\n    assert \"Acme Inc\" in task_payload[\"properties\"][\"hs_task_subject\"]\n    assert \"HOT\" in task_payload[\"properties\"][\"hs_task_subject\"]\n    assert task_payload[\"associations\"][0][\"to\"][\"id\"] == \"12345\"\n    assert task_payload[\"associations\"][0][\"types\"][0][\"associationTypeId\"] == 204\n\n    print(\"\\nBoth payloads match the shape HubSpot's API expects.\")\n", "verify": "Run `python hubspot_client.py` \u2014 you should see the contact payload with `'firstname': 'Jane'`, `'lastname': 'Okafor'` and `'lead_score': '9'`, then the task payload with `HOT` and `Acme Inc` in its subject line. No real HubSpot request is made."}], "goFurther": "Add a `find_contact_by_email(email)` function that POSTs to `/crm/v3/objects/contacts/search` first, so a lead who submits the form twice updates their existing contact instead of creating a duplicate."}, {"number": 4, "title": "Wire it all together", "time": "20 min", "description": "One Flask route, three imports. This file's whole job is calling webhook.py, scorer.py and hubspot_client.py in the right order and turning failures into a response Typeform can live with.", "steps": [{"instruction": "Create `main.py` with this code:", "prompt": "\"\"\"\nStep 4 of the Lead Capture & Qualifier Bot - the Flask app that ties\nwebhook parsing, AI scoring and HubSpot together.\n\nTest the wiring:    python main.py\nRun the real server: flask --app main run --port 5000\n\nThis file deliberately contains almost no logic of its own - parsing\nlives in webhook.py, scoring in scorer.py, HubSpot payloads in\nhubspot_client.py. main.py's only job is calling them in the right\norder and turning the result into an HTTP response. If a step's own\nbehaviour ever needs fixing, you'll know exactly which file to open.\n\"\"\"\n\nfrom flask import Flask, request, jsonify\n\nimport hubspot_client\nimport scorer\nfrom sdt_ai import AIError\nfrom webhook import parse_typeform_payload\n\napp = Flask(__name__)\n\n\n@app.route(\"/webhook/typeform\", methods=[\"POST\"])\ndef typeform_webhook():\n    payload = request.get_json(force=True, silent=True) or {}\n    lead = parse_typeform_payload(payload)\n\n    # Typeform only omits an answer if a question was skipped or bypassed\n    # by Logic Jump - but a lead with no email is useless to a sales\n    # team, so it's worth catching explicitly here rather than letting\n    # HubSpot reject it later with a less obvious error.\n    if not lead.get(\"email\"):\n        return jsonify({\"status\": \"ignored\", \"reason\": \"no email in submission\"}), 200\n\n    try:\n        result = scorer.score_lead(lead)\n    except AIError as problem:\n        # Returning 500 here would make Typeform retry the delivery a\n        # few minutes later, which would score (and could HubSpot-create)\n        # the same lead twice. Returning 200 with an error status stops\n        # the retry - you catch the failure by checking your own logs or\n        # Credits page, not by Typeform hammering the same URL.\n        return jsonify({\"status\": \"error\", \"stage\": \"scoring\", \"error\": str(problem)}), 200\n    except ValueError as problem:\n        return jsonify({\"status\": \"error\", \"stage\": \"scoring\", \"error\": str(problem)}), 200\n\n    try:\n        contact_id = hubspot_client.create_contact(lead, result)\n        hubspot_client.create_followup_task(contact_id, lead, result)\n    except Exception as problem:\n        # requests' raise_for_status() raises an error with HubSpot's own\n        # message attached - showing str(problem) surfaces the real cause\n        # (a missing scope, an unknown property) instead of hiding it\n        # behind a bare \"500 Internal Server Error\".\n        return jsonify({\"status\": \"error\", \"stage\": \"hubspot\", \"error\": str(problem)}), 200\n\n    return jsonify({\n        \"status\": \"ok\",\n        \"email\": lead[\"email\"],\n        \"score\": result[\"score\"],\n        \"tier\": result[\"tier\"],\n        \"contact_id\": contact_id,\n    }), 200\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the pipeline is wired correctly:\n    # python main.py\n    #\n    # This proves webhook.py -> scorer.py -> hubspot_client.py are all\n    # connected correctly, WITHOUT spending an AI credit or touching a\n    # real HubSpot account - it fakes both network calls, clearly\n    # commented below as fakes for this test only. To run the real\n    # server against real Typeform submissions, use the Flask CLI\n    # instead: flask --app main run --port 5000\n\n    FAKE_TYPEFORM_PAYLOAD = {\n        \"event_id\": \"LtWXD3crgy\",\n        \"event_type\": \"form_response\",\n        \"form_response\": {\n            \"form_id\": \"abc123\",\n            \"definition\": {\n                \"fields\": [\n                    {\"id\": \"f_name\", \"title\": \"Full name\", \"type\": \"short_text\"},\n                    {\"id\": \"f_email\", \"title\": \"Work email\", \"type\": \"email\"},\n                    {\"id\": \"f_company\", \"title\": \"Company name\", \"type\": \"short_text\"},\n                    {\"id\": \"f_size\", \"title\": \"Company size\", \"type\": \"multiple_choice\"},\n                    {\"id\": \"f_budget\", \"title\": \"Budget range\", \"type\": \"multiple_choice\"},\n                    {\"id\": \"f_challenge\", \"title\": \"What's your biggest challenge right now?\", \"type\": \"long_text\"},\n                ],\n            },\n            \"answers\": [\n                {\"type\": \"text\", \"text\": \"Jane Okafor\", \"field\": {\"id\": \"f_name\"}},\n                {\"type\": \"email\", \"email\": \"jane@acme.com\", \"field\": {\"id\": \"f_email\"}},\n                {\"type\": \"text\", \"text\": \"Acme Inc\", \"field\": {\"id\": \"f_company\"}},\n                {\"type\": \"choice\", \"choice\": {\"label\": \"51-200\"}, \"field\": {\"id\": \"f_size\"}},\n                {\"type\": \"choice\", \"choice\": {\"label\": \"$5k-$10k/month\"}, \"field\": {\"id\": \"f_budget\"}},\n                {\"type\": \"text\", \"text\": \"Our reporting is all manual spreadsheets.\", \"field\": {\"id\": \"f_challenge\"}},\n            ],\n        },\n    }\n\n    # FAKE for this test only: a canned AI reply, so this test costs zero\n    # credits and works even with no .env file at all. score_lead()'s own\n    # parsing and tier logic - the part actually worth testing here -\n    # still runs for real against this fake text.\n    def fake_ask_ai(prompt, **kwargs):\n        return \"[SCORE]\\n9\\n[REASON]\\nStrong fit on size and budget.\\n[END]\"\n\n    # FAKE for this test only: no real HubSpot account is needed to prove\n    # main.py calls create_contact() then create_followup_task() with the\n    # right arguments, in the right order.\n    def fake_send_to_hubspot(endpoint, payload, api_key):\n        if endpoint == \"/crm/v3/objects/contacts\":\n            return {\"id\": \"fake-contact-42\"}\n        return {\"id\": \"fake-task-99\"}\n\n    scorer.ask_ai = fake_ask_ai\n    hubspot_client.send_to_hubspot = fake_send_to_hubspot\n\n    with app.test_client() as client:\n        response = client.post(\"/webhook/typeform\", json=FAKE_TYPEFORM_PAYLOAD)\n        data = response.get_json()\n\n    print(\"Response:\", data)\n    assert response.status_code == 200, data\n    assert data[\"status\"] == \"ok\", data\n    assert data[\"score\"] == 9\n    assert data[\"tier\"] == \"hot\"\n    assert data[\"contact_id\"] == \"fake-contact-42\"\n    print(\"\\nPipeline wiring test passed: webhook -> score -> HubSpot all connected correctly.\")\n", "verify": "Run `python main.py` \u2014 you should see `Response: {...}` followed by `Pipeline wiring test passed: webhook -> score -> HubSpot all connected correctly.` This uses a fake AI reply and a fake HubSpot response, so it costs no credits and needs no HubSpot account yet."}, {"instruction": "Once the self-test passes, start the real server with `flask --app main run --port 5000`, then use a tunnel like ngrok (`ngrok http 5000`) to get a public URL and point your Typeform form's webhook (Connect \u2192 Webhooks) at `<your-ngrok-url>/webhook/typeform`.", "verify": "Submit a real response to your Typeform form. Within a few seconds you should see a new contact in HubSpot with `lead_score`, `lead_tier` and `ai_notes` filled in, plus an associated follow-up task."}], "goFurther": "The 24-hour follow-up window for warm and cold leads is a placeholder \u2014 a real sales team might want warm leads followed up same-day too. Adjust `FOLLOW_UP_HOURS` in `hubspot_client.py` and re-run `python main.py` to confirm the self-test still passes with your new numbers."}, {"number": 5, "phaseLabel": "\ud83c\udfaf Challenge", "title": "Challenge: Skip the AI call for leads you already know are bad", "time": "20 min", "description": "Not every decision needs an AI call. A free personal email address (gmail.com, yahoo.com, outlook.com) on a B2B form is almost always a bad fit \u2014 you don't need the AI's judgment to know that, and skipping the call saves a credit and removes a whole category of AI unpredictability from your qualified leads. This is the real test of whether you understand what the AI is for here, not just whether the pipeline runs.", "steps": [{"instruction": "In `scorer.py`, add a `FREE_EMAIL_DOMAINS` list containing `gmail.com`, `yahoo.com`, `outlook.com` and `hotmail.com`, and a function `is_free_email_domain(email)` that returns True if the email's domain (the part after `@`, lowercased) is in that list. Then, at the very top of `score_lead()`, before `build_prompt()` is called, check the lead's email with it \u2014 if it's a free domain, return `{\"score\": 1, \"tier\": \"cold\", \"reason\": \"Personal email domain \u2014 not a business lead.\"}` immediately, without calling `ask_ai()` at all.", "prompt": "def is_free_email_domain(email):\n    # TODO: pull out the part after \"@\", lowercase it, and check it\n    # against FREE_EMAIL_DOMAINS. Handle a missing \"@\" without crashing.\n    pass\n\n\ndef score_lead(lead):\n    # TODO: call is_free_email_domain(lead.get(\"email\", \"\")) here, before\n    # build_prompt() is ever called - return a fixed cold result\n    # immediately if it's True, instead of calling the AI at all.\n    ...\n", "verify": "Run `python -c \"from scorer import score_lead; print(score_lead({'full_name': 'Test', 'email': 'test@gmail.com', 'company': '', 'company_size': '', 'budget': '', 'challenge': ''}))\"` \u2014 it must print exactly `{'score': 1, 'tier': 'cold', 'reason': 'Personal email domain \u2014 not a business lead.'}`, and it must do so instantly with no `.env` file or AI Builder key required at all \u2014 proof the AI was never called."}]}], "portfolio": "You just built a lead qualification pipeline that turns a raw form submission into a scored, prioritized HubSpot contact with its own follow-up task \u2014 automatically, in seconds. Take a screenshot of a scored contact in HubSpot next to its follow-up task, and add \"Lead Capture & Qualifier Bot\" to your build portfolio with a one-line description.", "portfolioPrompt": "I just built a lead qualification pipeline: a Flask webhook receives Typeform submissions, an AI model scores each lead 1-10 against an Ideal Customer Profile and gives a one-line reason, and the result is pushed into HubSpot as a contact with a tiered (hot/warm/cold) follow-up task \u2014 with a rule-based shortcut that skips the AI call entirely for obviously-bad leads.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$::jsonb,
  null, null,
  $tsh$[{"issue": "The Typeform webhook never fires", "fix": "Webhooks need a publicly reachable URL \u2014 localhost alone will never work. Run `ngrok http 5000` while testing locally and point Typeform's webhook at the ngrok URL, then switch to your real deployed URL once it's live."}, {"issue": "scorer.py raises \"Could not find a numeric score in the AI's reply\"", "fix": "This is the AI-reliability failure this project is built to catch loudly instead of silently: the model replied without a [SCORE] section, or with no digit in it at all. Print the raw `reply` inside `score_lead()` to see exactly what came back \u2014 scorer.py's self-test already covers the most common drift (\"8/10\" instead of \"8\"), so a fresh failure usually means a new phrasing worth handling too."}, {"issue": "401 Unauthorized from the HubSpot API", "fix": "Your Private App's access token is missing a scope. Edit the private app in HubSpot, make sure `crm.objects.contacts.write` and `crm.objects.tasks.write` are both enabled, and copy the token again."}, {"issue": "HubSpot returns an error mentioning lead_score, lead_tier or ai_notes", "fix": "Those are custom contact properties this project assumes already exist. Create them under Settings \u2192 Properties \u2192 Contact properties before your first real submission (Build 3, step 2)."}, {"issue": "Duplicate contacts created for the same lead", "fix": "`create_contact()` in this starter always creates a new contact. Add a `find_contact_by_email()` search (see Build 3's \"Go further\") and update the existing contact instead of creating a new one when a match is found."}]$tsh$::jsonb,
  $res$[{"title": "Typeform Webhooks \u2014 example payload", "url": "https://www.typeform.com/developers/webhooks/example-payload/"}, {"title": "Typeform Webhooks overview", "url": "https://www.typeform.com/developers/webhooks/"}, {"title": "HubSpot Contacts API", "url": "https://developers.hubspot.com/docs/reference/api/crm/objects/contacts"}, {"title": "HubSpot Tasks API \u2014 Create", "url": "https://developers.hubspot.com/docs/api-reference/crm-tasks-v3/basic/post-crm-v3-objects-tasks"}]$res$::jsonb,
